const MIN_VOLUME = 20;
const THRESHOLD = 0.5;
function shouldTrip(outcomes) {
  const volume = outcomes.length;
  const failures = outcomes.reduce((a, b) => a + b, 0);
  const rate = volume === 0 ? 0 : failures / volume;
  return rate >= THRESHOLD;
}

tasks.verify:
